cssCode:
.liquid-glass-wrap {
  width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; position: relative;
}
.fluid-blob {
  position: absolute; width: 250px; height: 250px; background: #ff007f; border-radius: 50%;
  filter: blur(40px); animation: fluidWander 6s infinite alternate ease-in-out;
}
.glass-magnetic-card {
  width: 260px; height: 320px; background: rgba(255, 255, 255, 0.05); backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 20px; z-index: 10;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  transition: transform 0.2s ease-out; color: #fff; font-family: sans-serif;
}
@keyframes fluidWander { 0% { transform: translate(-50px, -50px); background: #ff007f; } 100% { transform: translate(50px, 50px); background: #00d2ff; } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

const wrap = document.createElement('div');
wrap.className = 'liquid-glass-wrap';

const blob = document.createElement('div');
blob.className = 'fluid-blob';

const card = document.createElement('div');
card.className = 'glass-magnetic-card';
card.innerHTML = '<h2 style="margin:0; font-size:40px;">🔮</h2><h3 style="letter-spacing:2px; margin-top:10px;">HYBRID</h3>';

wrap.appendChild(blob); wrap.appendChild(card); c.appendChild(wrap);

wrap.addEventListener('pointermove', (e) => {
  const rect = card.getBoundingClientRect();
  const x = (e.clientX - rect.left - rect.width/2) * 0.3;
  const y = (e.clientY - rect.top - rect.height/2) * 0.3;
  // Magnetic pull
  card.style.transform = `translate(${x}px, ${y}px)`;
});
wrap.addEventListener('pointerleave', () => { card.style.transform = `translate(0px, 0px)`; });
